import GHC.Prim (Addr#, Char#, Double#, Float#, Int#)

data List a = [] | a : [a]

infixr 5 :

data Int = I# Int#

data Char = C# Char#

data Float = F# Float#

data Double = D# Double#

data Bool = False | True

data Ordering = LT | EQ | GT

type Constraint :: Type
data Constraint

-- | The compiler proves that both types have the same representation.
type Coercible :: Type -> Type -> Constraint
class Coercible a b

-- | The compiler supplies nominal equality evidence for this class.
type (~) :: forall k. k -> k -> Constraint
class (a :: k) ~ (b :: k)

type (~~) :: forall k1 k2. k1 -> k2 -> Constraint
class (a :: k1) ~~ (b :: k2)

infix 4 ~

data TYPE (rep :: RuntimeRep)

type Type :: Type
type Type = TYPE LiftedRep

type UnliftedType = TYPE UnliftedRep

type LiftedRep :: RuntimeRep
type LiftedRep = 'BoxedRep 'Lifted

type UnliftedRep :: RuntimeRep
type UnliftedRep = 'BoxedRep 'Unlifted

data RuntimeRep
  = AddrRep
  | BoxedRep Levity
  | DoubleRep
  | FloatRep
  | Int16Rep
  | Int32Rep
  | Int64Rep
  | Int8Rep
  | IntRep
  | SumRep [RuntimeRep]
  | TupleRep [RuntimeRep]
  | VecRep VecCount VecElem
  | Word16Rep
  | Word32Rep
  | Word64Rep
  | Word8Rep
  | WordRep

data Levity = Lifted | Unlifted

data VecCount = Vec16 | Vec2 | Vec32 | Vec4 | Vec64 | Vec8

data VecElem
  = DoubleElemRep
  | FloatElemRep
  | Int16ElemRep
  | Int32ElemRep
  | Int64ElemRep
  | Int8ElemRep
  | Word16ElemRep
  | Word32ElemRep
  | Word64ElemRep
  | Word8ElemRep

-- | The package and the module that a type constructor was declared in.
data Module = Module TrName TrName

-- | A name in the type representation machinery. A static name comes from a
-- string literal in the compiled program; a dynamic one is built at run time.
data TrName
  = TrNameS Addr#
  | TrNameD [Char]

-- | A kind variable of a 'KindRep', named by its position in the kind
-- arguments of the type constructor that the representation belongs to.
type KindBndr = Int

-- | The kind of a type constructor, with its own kind arguments left as
-- 'KindRepVar' binders.
data KindRep
  = KindRepTyConApp TyCon [KindRep]
  | KindRepVar !KindBndr
  | KindRepApp KindRep KindRep
  | KindRepFun KindRep KindRep
  | KindRepTYPE !RuntimeRep
  | KindRepTypeLitS TypeLitSort Addr#
  | KindRepTypeLitD TypeLitSort [Char]

data TypeLitSort
  = TypeLitSymbol
  | TypeLitNat
  | TypeLitChar

-- | A type constructor, as the compiler builds it for the 'Typeable'
-- evidence of a type. GHC keeps a fingerprint in the first two fields and
-- compares constructors by it; aihc compares them by name and so has no
-- fingerprint to keep.
data TyCon = TyCon Module TrName Int KindRep

